program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row) and r == h - r - 1:
            split = ("h", r)
            break
    if split is None:
        for c in range(w):
            if all(row[c] == grid[0][c] for row in grid) and c == w - c - 1:
                split = ("v", c)
                break
    if split is None:
        raise ValueError("no centered uniform separator")
    axis, k = split
    if axis == "h":
        a, b = grid[:k], grid[k + 1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    ca, cb = Counter(v for row in a for v in row), Counter(v for row in b for v in row)
    bga, bgb = ca.most_common(1)[0][0], cb.most_common(1)[0][0]
    fga = next(v for v in ca if v != bga)
    fgb = next(v for v in cb if v != bgb)

    if bga == bgb:
        out_bg, out_fg, rule = 3, bga, "union"
    elif fga == fgb:
        out_bg, out_fg, rule = fga, 3, "intersection"
    elif fga == bgb:
        out_bg, out_fg, rule = fga, 3, "left_difference"
    elif fgb == bga:
        out_bg, out_fg, rule = fgb, 3, "right_difference"
    else:
        raise ValueError("unrecognized color relationship")

    out = []
    for ra, rb in zip(a, b):
        row = []
        for x, y in zip(ra, rb):
            ax, by = x == fga, y == fgb
            if rule == "union":
                mark = ax or by
            elif rule == "intersection":
                mark = ax and by
            elif rule == "left_difference":
                mark = ax and not by
            else:
                mark = by and not ax
            row.append(out_fg if mark else out_bg)
        out.append(row)
    return out
'''
